-- PostgreSQL application and authentication schema. User/profile IDs are UUIDs
-- generated by the Veyra API. Mirrors database/schema.sql (MariaDB).
-- DATETIME(3) columns are TIMESTAMP(3) stored in UTC; the API pins the session
-- timezone to UTC and normalizes ISO-8601 inputs before writes.
-- Apply to a new database with: USE_MARIADB=false npm run db:migrate

CREATE TABLE IF NOT EXISTS auth_users (
  id VARCHAR(36) NOT NULL PRIMARY KEY,
  email VARCHAR(320) NOT NULL UNIQUE,
  password_hash VARCHAR(255) NOT NULL,
  email_verified_at TIMESTAMP(3) NULL,
  created_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMP(3) NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS auth_identities (
  id VARCHAR(36) NOT NULL PRIMARY KEY,
  user_id VARCHAR(36) NOT NULL,
  provider VARCHAR(32) NOT NULL,
  provider_user_id VARCHAR(255) NOT NULL,
  created_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  CONSTRAINT uq_auth_identities_provider_user UNIQUE (provider, provider_user_id),
  CONSTRAINT fk_auth_identities_user FOREIGN KEY (user_id) REFERENCES auth_users(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_auth_identities_user ON auth_identities (user_id);

CREATE TABLE IF NOT EXISTS auth_sessions (
  id VARCHAR(36) NOT NULL PRIMARY KEY,
  user_id VARCHAR(36) NOT NULL,
  token_hash VARCHAR(64) NOT NULL UNIQUE,
  expires_at TIMESTAMP(3) NOT NULL,
  created_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  CONSTRAINT fk_auth_sessions_user FOREIGN KEY (user_id) REFERENCES auth_users(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_auth_sessions_user ON auth_sessions (user_id);

CREATE TABLE IF NOT EXISTS auth_native_codes (
  id VARCHAR(36) NOT NULL PRIMARY KEY,
  code_hash VARCHAR(64) NOT NULL UNIQUE,
  client_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(36) NULL,
  expires_at TIMESTAMP(3) NOT NULL,
  consumed_at TIMESTAMP(3) NULL,
  created_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  CONSTRAINT fk_auth_native_codes_user FOREIGN KEY (user_id) REFERENCES auth_users(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_auth_native_codes_expiry ON auth_native_codes (expires_at);
CREATE INDEX IF NOT EXISTS idx_auth_native_codes_user ON auth_native_codes (user_id);

CREATE TABLE IF NOT EXISTS auth_email_tokens (
  id VARCHAR(36) NOT NULL PRIMARY KEY,
  user_id VARCHAR(36) NOT NULL,
  token_hash VARCHAR(64) NOT NULL UNIQUE,
  purpose VARCHAR(16) NOT NULL CHECK (purpose IN ('confirm','reset')),
  expires_at TIMESTAMP(3) NOT NULL,
  created_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  CONSTRAINT fk_auth_email_tokens_user FOREIGN KEY (user_id) REFERENCES auth_users(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_auth_email_tokens_user_purpose ON auth_email_tokens (user_id, purpose);

CREATE TABLE IF NOT EXISTS profiles (
  id VARCHAR(36) NOT NULL PRIMARY KEY,
  username VARCHAR(32) NOT NULL UNIQUE,
  display_name VARCHAR(80) NULL,
  avatar_url TEXT NULL,
  banner_url TEXT NULL,
  banner_gradient VARCHAR(255) NULL,
  bio TEXT NULL,
  pronouns VARCHAR(80) NULL,
  status VARCHAR(32) NULL,
  username_set BOOLEAN NOT NULL DEFAULT FALSE,
  allow_friend_requests BOOLEAN NOT NULL DEFAULT TRUE,
  announcements_last_read_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  global_mentions_last_read_at TIMESTAMP(3) NULL,
  global_muted BOOLEAN NOT NULL DEFAULT FALSE,
  custom_status_text VARCHAR(140) NULL,
  custom_status_emoji VARCHAR(32) NULL,
  custom_status_set_at TIMESTAMP(3) NULL,
  custom_status_expires_at TIMESTAMP(3) NULL,
  created_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMP(3) NOT NULL DEFAULT NOW()
);
-- MariaDB's utf8mb4_unicode_ci collation is case-insensitive; enforce the same
-- uniqueness on lowercased usernames so 'Alice' and 'alice' cannot coexist.
CREATE UNIQUE INDEX IF NOT EXISTS uq_profiles_username_lower ON profiles (lower(username));

CREATE TABLE IF NOT EXISTS user_roles (
  id VARCHAR(36) NOT NULL PRIMARY KEY,
  user_id VARCHAR(36) NOT NULL,
  role VARCHAR(24) NOT NULL DEFAULT 'user' CHECK (role IN ('user','admin','super_admin')),
  created_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  CONSTRAINT uq_user_roles_user_role UNIQUE (user_id, role),
  CONSTRAINT fk_user_roles_profile FOREIGN KEY (user_id) REFERENCES profiles(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_user_roles_user ON user_roles (user_id);

CREATE TABLE IF NOT EXISTS conversations (
  id VARCHAR(36) NOT NULL PRIMARY KEY,
  is_group BOOLEAN NOT NULL DEFAULT FALSE,
  name VARCHAR(100) NULL,
  created_by VARCHAR(36) NULL,
  created_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  CONSTRAINT fk_conversations_creator FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_conversations_created_by ON conversations (created_by);

CREATE TABLE IF NOT EXISTS conversation_members (
  id VARCHAR(36) NOT NULL PRIMARY KEY,
  conversation_id VARCHAR(36) NOT NULL,
  user_id VARCHAR(36) NOT NULL,
  role VARCHAR(24) NOT NULL DEFAULT 'member',
  muted BOOLEAN NOT NULL DEFAULT FALSE,
  joined_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  CONSTRAINT uq_conversation_member UNIQUE (conversation_id, user_id),
  CONSTRAINT fk_conversation_members_conversation FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE,
  CONSTRAINT fk_conversation_members_profile FOREIGN KEY (user_id) REFERENCES profiles(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_conversation_members_user ON conversation_members (user_id);

CREATE TABLE IF NOT EXISTS friend_requests (
  id VARCHAR(36) NOT NULL PRIMARY KEY,
  sender_id VARCHAR(36) NOT NULL,
  receiver_id VARCHAR(36) NOT NULL,
  status VARCHAR(24) NOT NULL DEFAULT 'pending',
  created_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  CONSTRAINT uq_friend_request_pair UNIQUE (sender_id, receiver_id),
  CONSTRAINT fk_friend_requests_sender FOREIGN KEY (sender_id) REFERENCES profiles(id) ON DELETE CASCADE,
  CONSTRAINT fk_friend_requests_receiver FOREIGN KEY (receiver_id) REFERENCES profiles(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_friend_requests_receiver ON friend_requests (receiver_id, status);

CREATE TABLE IF NOT EXISTS messages (
  id VARCHAR(36) NOT NULL PRIMARY KEY,
  conversation_id VARCHAR(36) NOT NULL,
  sender_id VARCHAR(36) NULL,
  content TEXT NOT NULL,
  image_url TEXT NULL,
  reply_to_id VARCHAR(36) NULL,
  is_pinned BOOLEAN NOT NULL DEFAULT FALSE,
  pinned_at TIMESTAMP(3) NULL,
  pinned_by VARCHAR(36) NULL,
  read_at TIMESTAMP(3) NULL,
  delivered_at TIMESTAMP(3) NULL,
  edited_at TIMESTAMP(3) NULL,
  created_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  CONSTRAINT fk_messages_conversation FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE,
  CONSTRAINT fk_messages_sender FOREIGN KEY (sender_id) REFERENCES profiles(id) ON DELETE SET NULL,
  CONSTRAINT fk_messages_reply FOREIGN KEY (reply_to_id) REFERENCES messages(id) ON DELETE SET NULL,
  CONSTRAINT fk_messages_pinner FOREIGN KEY (pinned_by) REFERENCES profiles(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_messages_conversation_created ON messages (conversation_id, created_at);
CREATE INDEX IF NOT EXISTS idx_messages_sender ON messages (sender_id);
CREATE INDEX IF NOT EXISTS idx_messages_reply_to ON messages (reply_to_id);
CREATE INDEX IF NOT EXISTS idx_messages_conversation_read ON messages (conversation_id, read_at);

CREATE TABLE IF NOT EXISTS global_messages (
  id VARCHAR(36) NOT NULL PRIMARY KEY,
  sender_id VARCHAR(36) NULL,
  content TEXT NOT NULL,
  image_url TEXT NULL,
  reply_to_id VARCHAR(36) NULL,
  edited_at TIMESTAMP(3) NULL,
  created_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  CONSTRAINT fk_global_messages_sender FOREIGN KEY (sender_id) REFERENCES profiles(id) ON DELETE SET NULL,
  CONSTRAINT fk_global_messages_reply FOREIGN KEY (reply_to_id) REFERENCES global_messages(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_global_messages_created ON global_messages (created_at);

CREATE TABLE IF NOT EXISTS announcement_messages (
  id VARCHAR(36) NOT NULL PRIMARY KEY,
  sender_id VARCHAR(36) NULL,
  content TEXT NOT NULL,
  image_url TEXT NULL,
  reply_to_id VARCHAR(36) NULL,
  is_pinned BOOLEAN NOT NULL DEFAULT FALSE,
  pinned_at TIMESTAMP(3) NULL,
  pinned_by VARCHAR(36) NULL,
  edited_at TIMESTAMP(3) NULL,
  created_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  CONSTRAINT fk_announcement_sender FOREIGN KEY (sender_id) REFERENCES profiles(id) ON DELETE SET NULL,
  CONSTRAINT fk_announcement_reply FOREIGN KEY (reply_to_id) REFERENCES announcement_messages(id) ON DELETE SET NULL,
  CONSTRAINT fk_announcement_pinner FOREIGN KEY (pinned_by) REFERENCES profiles(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_announcement_messages_created ON announcement_messages (created_at);

CREATE TABLE IF NOT EXISTS message_reactions (
  id VARCHAR(36) NOT NULL PRIMARY KEY,
  message_id VARCHAR(36) NOT NULL,
  user_id VARCHAR(36) NOT NULL,
  emoji VARCHAR(32) NOT NULL,
  created_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  CONSTRAINT uq_message_reaction UNIQUE (message_id, user_id, emoji),
  -- message_id is polymorphic: it may reference messages, global_messages,
  -- or announcement_messages, so no single FK is possible.
  CONSTRAINT fk_reactions_profile FOREIGN KEY (user_id) REFERENCES profiles(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_message_reactions_message ON message_reactions (message_id);
CREATE INDEX IF NOT EXISTS idx_message_reactions_user ON message_reactions (user_id);

CREATE TABLE IF NOT EXISTS blocked_users (
  id VARCHAR(36) NOT NULL PRIMARY KEY,
  blocker_id VARCHAR(36) NOT NULL,
  blocked_id VARCHAR(36) NOT NULL,
  created_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  CONSTRAINT uq_blocked_users_pair UNIQUE (blocker_id, blocked_id),
  CONSTRAINT fk_blocker_profile FOREIGN KEY (blocker_id) REFERENCES profiles(id) ON DELETE CASCADE,
  CONSTRAINT fk_blocked_profile FOREIGN KEY (blocked_id) REFERENCES profiles(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS pinned_conversations (
  id VARCHAR(36) NOT NULL PRIMARY KEY,
  user_id VARCHAR(36) NOT NULL,
  conversation_id VARCHAR(36) NOT NULL,
  created_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  CONSTRAINT uq_pinned_conversation UNIQUE (user_id, conversation_id),
  CONSTRAINT fk_pinned_user FOREIGN KEY (user_id) REFERENCES profiles(id) ON DELETE CASCADE,
  CONSTRAINT fk_pinned_conversation FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS polls (
  id VARCHAR(36) NOT NULL PRIMARY KEY,
  channel VARCHAR(32) NOT NULL,
  conversation_id VARCHAR(36) NULL,
  created_by VARCHAR(36) NOT NULL,
  question TEXT NOT NULL,
  multiple_choice BOOLEAN NOT NULL DEFAULT FALSE,
  ends_at TIMESTAMP(3) NOT NULL,
  closed_at TIMESTAMP(3) NULL,
  message_id VARCHAR(36) NULL,
  result_message_id VARCHAR(36) NULL,
  created_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  CONSTRAINT fk_polls_creator FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE CASCADE,
  CONSTRAINT fk_polls_conversation FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_polls_channel ON polls (channel, conversation_id, created_at);

CREATE TABLE IF NOT EXISTS poll_options (
  id VARCHAR(36) NOT NULL PRIMARY KEY,
  poll_id VARCHAR(36) NOT NULL,
  text VARCHAR(255) NOT NULL,
  position INTEGER NOT NULL,
  created_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  CONSTRAINT fk_poll_options_poll FOREIGN KEY (poll_id) REFERENCES polls(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_poll_options_order ON poll_options (poll_id, position);

CREATE TABLE IF NOT EXISTS poll_votes (
  id VARCHAR(36) NOT NULL PRIMARY KEY,
  poll_id VARCHAR(36) NOT NULL,
  option_id VARCHAR(36) NOT NULL,
  user_id VARCHAR(36) NOT NULL,
  created_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  CONSTRAINT uq_poll_vote UNIQUE (poll_id, option_id, user_id),
  CONSTRAINT fk_poll_votes_poll FOREIGN KEY (poll_id) REFERENCES polls(id) ON DELETE CASCADE,
  CONSTRAINT fk_poll_votes_option FOREIGN KEY (option_id) REFERENCES poll_options(id) ON DELETE CASCADE,
  CONSTRAINT fk_poll_votes_profile FOREIGN KEY (user_id) REFERENCES profiles(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_poll_votes_user ON poll_votes (poll_id, user_id);

CREATE TABLE IF NOT EXISTS admin_logs (
  id VARCHAR(36) NOT NULL PRIMARY KEY,
  admin_id VARCHAR(36) NOT NULL,
  action VARCHAR(100) NOT NULL,
  target_type VARCHAR(100) NOT NULL,
  target_id VARCHAR(36) NULL,
  details JSONB NULL,
  created_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  CONSTRAINT fk_admin_logs_admin FOREIGN KEY (admin_id) REFERENCES profiles(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_admin_logs_created ON admin_logs (created_at);
CREATE INDEX IF NOT EXISTS idx_admin_logs_admin ON admin_logs (admin_id);

CREATE TABLE IF NOT EXISTS notification_preferences (
  user_id VARCHAR(36) NOT NULL PRIMARY KEY,
  ntfy_server VARCHAR(512) NOT NULL DEFAULT 'https://ntfy.sh',
  ntfy_topic VARCHAR(255) NULL,
  dm_mode VARCHAR(16) NOT NULL DEFAULT 'every',
  dm_custom_enabled BOOLEAN NOT NULL DEFAULT FALSE,
  dm_title_template VARCHAR(255) NOT NULL DEFAULT 'New message from {sender}',
  dm_body_template TEXT NOT NULL DEFAULT '{message}',
  global_mode VARCHAR(16) NOT NULL DEFAULT 'off',
  global_custom_enabled BOOLEAN NOT NULL DEFAULT FALSE,
  global_title_template VARCHAR(255) NOT NULL DEFAULT 'New message in global chat',
  global_body_template TEXT NOT NULL DEFAULT '{sender}: {message}',
  announcement_mode VARCHAR(16) NOT NULL DEFAULT 'every',
  announcement_custom_enabled BOOLEAN NOT NULL DEFAULT FALSE,
  announcement_title_template VARCHAR(255) NOT NULL DEFAULT 'New announcement',
  announcement_body_template TEXT NOT NULL DEFAULT '{message}',
  digest_cooldown_minutes INTEGER NOT NULL DEFAULT 15,
  created_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  CONSTRAINT fk_notification_preferences_profile FOREIGN KEY (user_id) REFERENCES profiles(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS notification_digest_state (
  user_id VARCHAR(36) NOT NULL,
  channel_key VARCHAR(64) NOT NULL,
  last_notified_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  PRIMARY KEY (user_id, channel_key),
  CONSTRAINT fk_notification_digest_profile FOREIGN KEY (user_id) REFERENCES profiles(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS notification_trigger_events (
  id VARCHAR(36) NOT NULL PRIMARY KEY,
  channel VARCHAR(32) NOT NULL,
  message_id VARCHAR(36) NOT NULL,
  token VARCHAR(128) NOT NULL,
  created_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  CONSTRAINT uq_notification_trigger UNIQUE (token)
);
CREATE INDEX IF NOT EXISTS idx_notification_trigger_created ON notification_trigger_events (created_at);

CREATE TABLE IF NOT EXISTS native_push_tokens (
  id VARCHAR(36) NOT NULL PRIMARY KEY,
  user_id VARCHAR(36) NOT NULL,
  token TEXT NOT NULL,
  platform VARCHAR(32) NOT NULL,
  device_id VARCHAR(255) NULL,
  enabled BOOLEAN NOT NULL DEFAULT TRUE,
  last_seen_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  created_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  CONSTRAINT fk_native_push_profile FOREIGN KEY (user_id) REFERENCES profiles(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_native_push_tokens_user ON native_push_tokens (user_id);

-- MariaDB's ON UPDATE CURRENT_TIMESTAMP(3) equivalent: keep updated_at fresh
-- on every UPDATE for tables that expose it.
CREATE OR REPLACE FUNCTION veyra_touch_updated_at() RETURNS trigger AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DO $$
DECLARE
  tbl TEXT;
BEGIN
  FOREACH tbl IN ARRAY ARRAY[
    'auth_users', 'profiles', 'conversations', 'friend_requests', 'messages',
    'global_messages', 'announcement_messages', 'polls', 'servers',
    'notification_preferences', 'native_push_tokens'
  ]
  LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS trg_%I_touch_updated_at ON %I', tbl, tbl);
    EXECUTE format('CREATE TRIGGER trg_%I_touch_updated_at BEFORE UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION veyra_touch_updated_at()', tbl, tbl);
  END LOOP;
END $$;

-- ---------------------------------------------------------------------------
-- 1.2.5 additions (idempotent � safe to re-run on existing databases)
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS dm_pairs (
  user_low VARCHAR(36) NOT NULL,
  user_high VARCHAR(36) NOT NULL,
  conversation_id VARCHAR(36) NOT NULL,
  created_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  PRIMARY KEY (user_low, user_high),
  CONSTRAINT fk_dm_pairs_conversation FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_dm_pairs_conversation ON dm_pairs (conversation_id);

-- message_reactions.message_id is polymorphic (messages / global_messages /
-- announcement_messages); the old messages-only FK must go.
ALTER TABLE message_reactions DROP CONSTRAINT IF EXISTS fk_reactions_message;
ALTER TABLE conversation_members ADD COLUMN IF NOT EXISTS muted BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE profiles ADD COLUMN IF NOT EXISTS global_muted BOOLEAN NOT NULL DEFAULT FALSE;

-- Backfill dm_pairs for existing 1:1 conversations so ensureDirectMessage can
-- dedupe atomically. Only exactly-two-member non-group conversations qualify.
INSERT INTO dm_pairs (user_low, user_high, conversation_id)
SELECT LEAST(a.user_id, b.user_id), GREATEST(a.user_id, b.user_id), c.id
FROM conversations c
JOIN conversation_members a ON a.conversation_id = c.id
JOIN conversation_members b ON b.conversation_id = c.id AND b.user_id > a.user_id
WHERE c.is_group = FALSE
  AND (SELECT COUNT(*) FROM conversation_members cm WHERE cm.conversation_id = c.id) = 2
ON CONFLICT DO NOTHING;

-- ---------------------------------------------------------------------------
-- 1.3.0 additions (idempotent — safe to re-run on existing databases)
-- ---------------------------------------------------------------------------

ALTER TABLE conversations ADD COLUMN IF NOT EXISTS kind VARCHAR(16) NOT NULL DEFAULT 'dm';
ALTER TABLE conversations ADD COLUMN IF NOT EXISTS avatar_url TEXT NULL;
ALTER TABLE messages ADD COLUMN IF NOT EXISTS preview VARCHAR(280) NULL;

UPDATE conversations SET kind = 'group' WHERE is_group = TRUE AND kind = 'dm';
UPDATE conversations SET kind = 'dm' WHERE is_group = FALSE AND kind <> 'dm';

ALTER TABLE friend_requests ADD COLUMN IF NOT EXISTS user_low VARCHAR(36) NULL;
ALTER TABLE friend_requests ADD COLUMN IF NOT EXISTS user_high VARCHAR(36) NULL;
UPDATE friend_requests SET user_low = LEAST(sender_id, receiver_id), user_high = GREATEST(sender_id, receiver_id) WHERE user_low IS NULL OR user_high IS NULL;

-- Collapse legacy directional duplicates to one row per unordered pair. Keep
-- the strongest relationship: accepted > pending > rejected/cancelled, then
-- the oldest row for deterministic ties.
DELETE FROM friend_requests fr
USING friend_requests keep
WHERE keep.user_low = fr.user_low
  AND keep.user_high = fr.user_high
  AND keep.id <> fr.id
  AND (
    CASE keep.status WHEN 'accepted' THEN 3 WHEN 'pending' THEN 2 ELSE 1 END
      > CASE fr.status WHEN 'accepted' THEN 3 WHEN 'pending' THEN 2 ELSE 1 END
    OR (
      CASE keep.status WHEN 'accepted' THEN 3 WHEN 'pending' THEN 2 ELSE 1 END
        = CASE fr.status WHEN 'accepted' THEN 3 WHEN 'pending' THEN 2 ELSE 1 END
      AND (keep.created_at < fr.created_at OR (keep.created_at = fr.created_at AND keep.id < fr.id))
    )
  );

ALTER TABLE friend_requests ALTER COLUMN user_low SET NOT NULL;
ALTER TABLE friend_requests ALTER COLUMN user_high SET NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_friend_request_pair_normalized ON friend_requests (user_low, user_high);
CREATE INDEX IF NOT EXISTS idx_friend_requests_pair ON friend_requests (user_low, user_high);

CREATE TABLE IF NOT EXISTS servers (
  id VARCHAR(36) NOT NULL PRIMARY KEY,
  name VARCHAR(100) NOT NULL,
  icon_url TEXT NULL,
  banner_url TEXT NULL,
  description VARCHAR(500) NULL,
  owner_id VARCHAR(36) NOT NULL,
  verification_level VARCHAR(16) NOT NULL DEFAULT 'none',
  created_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  CONSTRAINT fk_servers_owner FOREIGN KEY (owner_id) REFERENCES profiles(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_servers_owner ON servers (owner_id);

CREATE TABLE IF NOT EXISTS server_roles (
  id VARCHAR(36) NOT NULL PRIMARY KEY,
  server_id VARCHAR(36) NOT NULL,
  name VARCHAR(100) NOT NULL,
  color VARCHAR(9) NULL,
  position INTEGER NOT NULL DEFAULT 0,
  hoist BOOLEAN NOT NULL DEFAULT FALSE,
  mentionable BOOLEAN NOT NULL DEFAULT FALSE,
  is_default BOOLEAN NOT NULL DEFAULT FALSE,
  administrator BOOLEAN NOT NULL DEFAULT FALSE,
  permissions JSONB NOT NULL,
  created_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  CONSTRAINT uq_server_roles_name UNIQUE (server_id, name),
  CONSTRAINT fk_server_roles_server FOREIGN KEY (server_id) REFERENCES servers(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_server_roles_server ON server_roles (server_id, position);

CREATE TABLE IF NOT EXISTS server_members (
  id VARCHAR(36) NOT NULL PRIMARY KEY,
  server_id VARCHAR(36) NOT NULL,
  user_id VARCHAR(36) NOT NULL,
  role_id VARCHAR(36) NULL,
  nickname VARCHAR(80) NULL,
  timed_out_until TIMESTAMP(3) NULL,
  joined_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  CONSTRAINT uq_server_member UNIQUE (server_id, user_id),
  CONSTRAINT fk_server_members_server FOREIGN KEY (server_id) REFERENCES servers(id) ON DELETE CASCADE,
  CONSTRAINT fk_server_members_profile FOREIGN KEY (user_id) REFERENCES profiles(id) ON DELETE CASCADE,
  CONSTRAINT fk_server_members_role FOREIGN KEY (role_id) REFERENCES server_roles(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_server_members_user ON server_members (user_id);
CREATE INDEX IF NOT EXISTS idx_server_members_role ON server_members (role_id);

CREATE TABLE IF NOT EXISTS server_categories (
  id VARCHAR(36) NOT NULL PRIMARY KEY,
  server_id VARCHAR(36) NOT NULL,
  name VARCHAR(100) NOT NULL,
  position INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  CONSTRAINT fk_server_categories_server FOREIGN KEY (server_id) REFERENCES servers(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_server_categories_server ON server_categories (server_id, position);

CREATE TABLE IF NOT EXISTS server_channels (
  id VARCHAR(36) NOT NULL PRIMARY KEY,
  server_id VARCHAR(36) NOT NULL,
  conversation_id VARCHAR(36) NOT NULL,
  name VARCHAR(100) NOT NULL,
  type VARCHAR(16) NOT NULL DEFAULT 'text',
  category_id VARCHAR(36) NULL,
  position INTEGER NOT NULL DEFAULT 0,
  topic VARCHAR(500) NULL,
  slow_mode_seconds INTEGER NOT NULL DEFAULT 0,
  is_readonly BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  CONSTRAINT uq_server_channel_conversation UNIQUE (conversation_id),
  CONSTRAINT fk_server_channels_server FOREIGN KEY (server_id) REFERENCES servers(id) ON DELETE CASCADE,
  CONSTRAINT fk_server_channels_conversation FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE,
  CONSTRAINT fk_server_channels_category FOREIGN KEY (category_id) REFERENCES server_categories(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_server_channels_server ON server_channels (server_id, position);
CREATE INDEX IF NOT EXISTS idx_server_channels_category ON server_channels (category_id);

CREATE TABLE IF NOT EXISTS server_bans (
  id VARCHAR(36) NOT NULL PRIMARY KEY,
  server_id VARCHAR(36) NOT NULL,
  user_id VARCHAR(36) NOT NULL,
  banned_by VARCHAR(36) NULL,
  reason VARCHAR(300) NULL,
  created_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  CONSTRAINT uq_server_ban UNIQUE (server_id, user_id),
  CONSTRAINT fk_server_bans_server FOREIGN KEY (server_id) REFERENCES servers(id) ON DELETE CASCADE,
  CONSTRAINT fk_server_bans_profile FOREIGN KEY (user_id) REFERENCES profiles(id) ON DELETE CASCADE,
  CONSTRAINT fk_server_bans_actor FOREIGN KEY (banned_by) REFERENCES profiles(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_server_bans_user ON server_bans (user_id);

CREATE TABLE IF NOT EXISTS server_invites (
  id VARCHAR(36) NOT NULL PRIMARY KEY,
  server_id VARCHAR(36) NOT NULL,
  code VARCHAR(32) NOT NULL UNIQUE,
  created_by VARCHAR(36) NOT NULL,
  max_uses INTEGER NULL,
  uses INTEGER NOT NULL DEFAULT 0,
  expires_at TIMESTAMP(3) NULL,
  revoked_at TIMESTAMP(3) NULL,
  created_at TIMESTAMP(3) NOT NULL DEFAULT NOW(),
  CONSTRAINT fk_server_invites_server FOREIGN KEY (server_id) REFERENCES servers(id) ON DELETE CASCADE,
  CONSTRAINT fk_server_invites_creator FOREIGN KEY (created_by) REFERENCES profiles(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_server_invites_server ON server_invites (server_id);
